  ('36d6fd9a-648a-460c-a2b6-d7d5879ffd1c', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '3091d308-8cce-4a4d-8327-3750c04a710d', 'subtopic'::public.curated_course_node_type, 'Mandated reporting', 'Know jurisdiction-specific duties, thresholds, procedures, documentation, and consultation pathways.', 0),
  ('a2036b86-6452-455f-a584-426f2566d3ad', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '36d6fd9a-648a-460c-a2b6-d7d5879ffd1c', 'concept'::public.curated_course_node_type, 'Child and vulnerable-adult maltreatment', null, 0),
  ('68ac06b3-70bd-4904-83f1-89abcb9944dc', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '36d6fd9a-648a-460c-a2b6-d7d5879ffd1c', 'concept'::public.curated_course_node_type, 'Imminent danger and duty-to-protect concepts', null, 1),
  ('c246643d-f7be-4fb7-8ccc-daced12ab3c0', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '36d6fd9a-648a-460c-a2b6-d7d5879ffd1c', 'concept'::public.curated_course_node_type, 'Explaining limits of confidentiality', null, 2),
  ('ab419dcf-3d83-4d78-86be-5181219745d4', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '3091d308-8cce-4a4d-8327-3750c04a710d', 'subtopic'::public.curated_course_node_type, 'Collaborative safety planning', 'Create individualized, practical plans rather than relying on generic promises of safety.', 1),
  ('76e200b6-3621-4d49-9ed2-102225428c62', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'ab419dcf-3d83-4d78-86be-5181219745d4', 'concept'::public.curated_course_node_type, 'Warning signs and internal coping', null, 0),
  ('9fcf995d-8dc3-4c27-b43f-cf77c6061b2d', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'ab419dcf-3d83-4d78-86be-5181219745d4', 'concept'::public.curated_course_node_type, 'Social supports and professional contacts', null, 1),
  ('cd1fdc43-9b44-4218-a324-0d2c698cfc4e', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'ab419dcf-3d83-4d78-86be-5181219745d4', 'concept'::public.curated_course_node_type, 'Environmental and lethal-means safety', null, 2),
  ('c3b39803-94ac-4fc2-86b2-ea49f6de930d', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '3091d308-8cce-4a4d-8327-3750c04a710d', 'subtopic'::public.curated_course_node_type, 'Coordinated referral', 'Match need, eligibility, access, culture, urgency, and client preference, then close the loop.', 2),
  ('e94e000f-6afe-4ca5-a2d4-c9afccf99b9c', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'c3b39803-94ac-4fc2-86b2-ea49f6de930d', 'concept'::public.curated_course_node_type, 'Resource verification and barrier reduction', null, 0),
  ('6c49bbae-20bc-490b-852a-4b49d884331f', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'c3b39803-94ac-4fc2-86b2-ea49f6de930d', 'concept'::public.curated_course_node_type, 'Warm handoffs and releases of information', null, 1),
  ('d58e12e7-281d-4660-92fb-7ad57ff247f9', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'c3b39803-94ac-4fc2-86b2-ea49f6de930d', 'concept'::public.curated_course_node_type, 'Follow-up ownership and failed-referral plans', null, 2),
  ('2befe434-8938-4465-8495-1ec5ad1b2106', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', null, 'topic'::public.curated_course_node_type, '12. Ethics, Boundaries, Documentation, and Technology', 'Use professional authority responsibly through ethical reasoning, clear boundaries, defensible records, privacy protection, and safe technology use.', 11),
  ('6eed820c-6d25-4596-ac88-2bf94da4cc45', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '2befe434-8938-4465-8495-1ec5ad1b2106', 'subtopic'::public.curated_course_node_type, 'Ethical decision-making', 'Apply the NASW Code, law, policy, consultation, and principled reasoning to competing obligations.', 0),
  ('1a411cc9-5b3f-4830-8c6c-79a4a78dac40', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '6eed820c-6d25-4596-ac88-2bf94da4cc45', 'concept'::public.curated_course_node_type, 'Self-determination and foreseeable harm', null, 0),
  ('ecd71b96-14c6-4df1-921f-0ea73ad0470c', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '6eed820c-6d25-4596-ac88-2bf94da4cc45', 'concept'::public.curated_course_node_type, 'Conflicts of interest and dual relationships', null, 1),
  ('0c6691d3-505b-4c8b-95f9-9081f6945d4b', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '6eed820c-6d25-4596-ac88-2bf94da4cc45', 'concept'::public.curated_course_node_type, 'Competence, supervision, and impairment', null, 2),
  ('6cfd68df-92ce-4cd8-835b-be6870efd255', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '2befe434-8938-4465-8495-1ec5ad1b2106', 'subtopic'::public.curated_course_node_type, 'Boundaries and professional use of self', 'Use authenticity and self-disclosure only when they serve client goals and preserve role clarity.', 1),
  ('3a9d4884-72b1-42b1-aeec-45a4c4cf4956', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '6cfd68df-92ce-4cd8-835b-be6870efd255', 'concept'::public.curated_course_node_type, 'Gifts, touch, social contact, and social media', null, 0),
  ('93459f87-3d28-4408-a590-2acef5c7a738', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '6cfd68df-92ce-4cd8-835b-be6870efd255', 'concept'::public.curated_course_node_type, 'Countertransference and emotional reactions', null, 1),
  ('56c4b5ef-5eb6-42fb-a973-d674c811ebff', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '6cfd68df-92ce-4cd8-835b-be6870efd255', 'concept'::public.curated_course_node_type, 'Power, dependence, and ending', null, 2),
  ('a175c5ee-5417-42ae-ae06-2c11c4724433', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '2befe434-8938-4465-8495-1ec5ad1b2106', 'subtopic'::public.curated_course_node_type, 'Documentation and digital practice', 'Create timely, objective, useful records and protect information across in-person and electronic services.', 2),
  ('c5c9434e-9244-4c3f-ae8d-3d529b56da1e', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'a175c5ee-5417-42ae-ae06-2c11c4724433', 'concept'::public.curated_course_node_type, 'SOAP/DAP-style structure and clinical reasoning', null, 0),
  ('365e5e62-4487-4850-93de-2c4b67e48d3a', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'a175c5ee-5417-42ae-ae06-2c11c4724433', 'concept'::public.curated_course_node_type, 'Minimum necessary disclosure and releases', null, 1),
  ('d68e186e-16c6-4089-803e-58b662b6e278', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'a175c5ee-5417-42ae-ae06-2c11c4724433', 'concept'::public.curated_course_node_type, 'Telepractice consent, identity, location, privacy, and emergency plans', null, 2),
  ('cad8b0ba-310e-4481-8bfa-6d929c5f8498', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', null, 'topic'::public.curated_course_node_type, '13. Anti-Oppressive, Culturally Responsive, and Trauma-Informed Practice', 'Integrate cultural humility, power analysis, intersectionality, trauma knowledge, accessibility, and client expertise throughout practice.', 12),
  ('e4b7ba77-99a0-4374-bfa9-ca74d70e4ca6', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'cad8b0ba-310e-4481-8bfa-6d929c5f8498', 'subtopic'::public.curated_course_node_type, 'Cultural humility and anti-oppressive practice', 'Examine positionality and institutional power while treating culture as dynamic and client-defined.', 0),
  ('cc3fbc34-4cda-46d5-a257-e0f72564fabf', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'e4b7ba77-99a0-4374-bfa9-ca74d70e4ca6', 'concept'::public.curated_course_node_type, 'Intersectionality and structural oppression', null, 0),
  ('60211863-e3c2-4aa6-9099-7f971f8546c3', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', 'e4b7ba77-99a0-4374-bfa9-ca74d70e4ca6', 'concept'::public.curated_course_node_type, 'Microaggressions and repair', null, 1);
