  ('f6f6310b-21fc-459e-9086-77db1f004c4d', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '02476bfd-8ece-48a1-99dc-b6096e4def9e', 'concept'::public.curated_course_node_type, 'Measurement-based and feedback-informed care', null, 2),
