  ('59dfbbd9-4647-42b2-8b4c-7f41f04ece4e', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '65f00b81-18eb-4989-943f-875ff5708ce4', 'concept'::public.curated_course_node_type, 'Anxiety, depression, grief, and adjustment', null, 0),
