  ('00958ede-1836-4e6b-9ede-6c0d550ecbcb', 'b9c0d1e2-4f5a-4b59-8c89-9d0e1f2a3b99', '874104ee-ffc3-4a1e-a3cf-0ea2e08d9fb2', 'concept'::public.curated_course_node_type, 'Referral for specialized assessment or treatment', null, 2),
