update public.learning_paths
set
  title = 'Social Work Practice with Individuals and Families',
  goal = 'Social Work Practice with Individuals and Families',
  summary = 'Supervised generalist methods for working with individuals and families across engagement, assessment, planning, intervention, crisis response, referral, evaluation, and termination. Students practice relational and interviewing skills; CBT-informed, solution-focused, motivational, and family-systems strategies; trauma-informed and anti-oppressive care; ethical reasoning; documentation; technology use; case coordination; supervision; and feedback-informed improvement. Person-in-environment, strengths, human rights, safety, culture, and structural conditions organize the course.',
  data = $swifjson${"slug": "social-work-practice-with-individuals-and-families", "title": "Social Work Practice with Individuals and Families", "description": "Supervised generalist methods for working with individuals and families across engagement, assessment, planning, intervention, crisis response, referral, evaluation, and termination. Students practice relational and interviewing skills; CBT-informed, solution-focused, motivational, and family-systems strategies; trauma-informed and anti-oppressive care; ethical reasoning; documentation; technology use; case coordination; supervision; and feedback-informed improvement. Person-in-environment, strengths, human rights, safety, culture, and structural conditions organize the course.", "topics": [{"id": "0c9ad81e-8f8d-4d5c-9b78-f160b109403e", "type": "topic", "title": "1. Engagement", "description": "Build purposeful, collaborative helping relationships while recognizing power, culture, context, consent, and client self-determination.", "children": [{"id": "aa644409-15aa-481e-b323-8d08338e7398", "type": "subtopic", "title": "Preparing for first contact", "children": [{"id": "aeb2ff0c-4a93-4914-84b2-c4493fec1018", "type": "concept", "title": "Voluntary and involuntary service contexts"}, {"id": "578cb1d9-ee96-46cf-ae8b-0745a422c51d", "type": "concept", "title": "Physical, communication, and disability access"}, {"id": "61b74a56-9aac-4c55-ac12-6dab43091b58", "type": "concept", "title": "Worker assumptions and emotional preparation"}], "description": "Clarify role, setting, referral context, available information, accessibility, and immediate safety before beginning."}, {"id": "b65d994c-a75b-40ba-8175-6e5ac94c3518", "type": "subtopic", "title": "Relationship-building skills", "children": [{"id": "22e228cc-bfbe-4c46-a8ca-0a5423e279df", "type": "concept", "title": "Attending, open questions, reflection, and summarizing"}, {"id": "69057fee-a242-4902-9448-dbf4e1773af7", "type": "concept", "title": "Validation without premature agreement"}, {"id": "c4784acb-a734-4c91-9efd-11177b458c82", "type": "concept", "title": "Repairing misattunement and rupture"}], "description": "Use presence and communication skills that convey respect, curiosity, reliability, and empathy."}, {"id": "32cb2ddf-8051-429e-b1e1-cc841a425e93", "type": "subtopic", "title": "Informed participation", "children": [{"id": "1c1f22d7-e1d5-41c9-b489-6ecd9ba94dc8", "type": "concept", "title": "Plain-language informed consent"}, {"id": "279db870-4469-4815-a9b5-66af2d105a1d", "type": "concept", "title": "Client rights and grievance pathways"}, {"id": "a6137c1f-93b1-4a0a-8b1f-b71b12f9fe9d", "type": "concept", "title": "Shared expectations and early alliance monitoring"}], "description": "Explain services, limits, choices, privacy, records, fees if relevant, and how decisions will be made."}]}, {"id": "c186582d-518f-4c9c-b3bc-64e5f18b7a58", "type": "topic", "title": "2. Assessment", "description": "Develop a collaborative, multidimensional understanding of concerns, strengths, risks, relationships, resources, and structural context.", "children": [{"id": "95b3f6bc-7626-4cae-9637-392bf3d6e47b", "type": "subtopic", "title": "Biopsychosocial-spiritual assessment", "children": [{"id": "3986b1f5-af99-4cbb-b241-1e68fe0cf961", "type": "concept", "title": "Presenting concern and timeline"}, {"id": "d5fd69ea-f87c-4a2d-89ad-893077b9f6d3", "type": "concept", "title": "Functioning across life domains"}, {"id": "803b8e6d-34f4-4ecc-a9c6-33624002cca0", "type": "concept", "title": "Health, medication, substance use, and disability"}], "description": "Organize information across health, development, emotions, behavior, cognition, relationships, meaning, and environment."}, {"id": "4829bd4a-435c-4d11-a3cf-af4be437978a", "type": "subtopic", "title": "Strengths and person-in-environment", "children": [{"id": "6025e565-5cd1-46fd-9c6e-3d59b5a3d9c5", "type": "concept", "title": "Protective factors and resilience"}, {"id": "e68d911a-0978-4b04-9dc3-cb2b944fec95", "type": "concept", "title": "Genograms and ecomaps"}, {"id": "adc6608f-477e-4794-a545-cd5af50395df", "type": "concept", "title": "Housing, income, education, work, legal, and community context"}], "description": "Identify capabilities, culture, relationships, resources, oppression, and environmental fit—not only deficits."}, {"id": "b410806f-03cf-41cc-a7c0-579e1c7473c2", "type": "subtopic", "title": "Clinical and contextual formulation", "children": [{"id": "021fede5-9835-4576-8fec-f68649c91901", "type": "concept", "title": "Developmental and family context"}, {"id": "9fb5e66f-f4e4-4f7d-a45a-118894c90d61", "type": "concept", "title": "Differential possibilities within BSW scope"}, {"id": "e119fad0-370d-4a20-a8ce-0cfdb11a6e01", "type": "concept", "title": "Uncertainty, consultation, and reassessment"}], "description": "Synthesize patterns and hypotheses while distinguishing observation, client meaning, and worker inference."}]}, {"id": "c1704703-b8b9-4b07-b434-ece15086280d", "type": "topic", "title": "3. Goal Setting and Contracting", "description": "Translate assessment into client-owned priorities, observable goals, roles, and a practical working agreement.", "children": [{"id": "d0bd197c-9e2a-4e3f-b603-aa7160b73588", "type": "subtopic", "title": "Collaborative priorities", "children": [{"id": "d8175730-d4b1-40f7-bd70-42bb0a783e9e", "type": "concept", "title": "Values and preferred future"}, {"id": "9af14a5e-c04b-4b46-bab7-0f58f5f90b95", "type": "concept", "title": "Readiness, confidence, and barriers"}, {"id": "c44b52d5-bb6e-4e02-a88e-cd51e7bc5b28", "type": "concept", "title": "Family and system priorities"}], "description": "Elicit what matters to the client and negotiate competing needs, mandates, and urgency."}, {"id": "2155de4d-c4b9-4385-8668-60e8940a4331", "type": "subtopic", "title": "Goal quality", "children": [{"id": "4464fdea-c8d7-40bc-97f2-34de7656e362", "type": "concept", "title": "Behavioral and functional indicators"}, {"id": "a82514f6-a217-456d-b9f1-0d48360708a5", "type": "concept", "title": "Incremental and maintenance goals"}, {"id": "4fc9ec92-9149-4710-bdc9-b2464ffd3db1", "type": "concept", "title": "Equity and accessibility of expectations"}], "description": "Create specific, meaningful, attainable, relevant, and time-sensitive outcomes without oversimplifying complex change."}, {"id": "930b5d18-4417-438b-955a-77297472e32c", "type": "subtopic", "title": "Working agreement", "children": [{"id": "74328d09-2ab7-44a7-9df1-1c1441e450ae", "type": "concept", "title": "Consent and shared decision-making"}, {"id": "4570f746-be33-4795-9a02-a154f98d1aa6", "type": "concept", "title": "Attendance and between-session plans"}, {"id": "3c5f9251-aab3-4dd2-8962-b1ba4364d293", "type": "concept", "title": "Progress review and renegotiation"}], "description": "Specify roles, methods, frequency, communication, review points, and contingencies."}]}, {"id": "147248f8-afca-49d6-87c5-7a37b0952b26", "type": "topic", "title": "4. Intervention Planning", "description": "Select coordinated actions that fit the formulation, goals, evidence, culture, resources, risks, preferences, and scope of practice.", "children": [{"id": "e80daf88-b272-49e3-911c-5a72fdace96e", "type": "subtopic", "title": "Case conceptualization to action", "children": [{"id": "4a815ec2-6458-42e2-bfc2-5d4d1802bc04", "type": "concept", "title": "Target, method, dose, and sequence"}, {"id": "0633d453-4ca9-493b-a0b3-1a733c14850b", "type": "concept", "title": "Individual, family, environmental, and advocacy actions"}, {"id": "d8d07479-4409-4be8-b257-6bb34932150c", "type": "concept", "title": "Contraindications and referral needs"}], "description": "Link each intervention to a hypothesized mechanism and desired outcome."}, {"id": "f6c65147-a175-46a0-a391-a75d1b1d8e06", "type": "subtopic", "title": "Shared plan", "children": [{"id": "7a5e9276-3016-47d5-b988-4072aa239dca", "type": "concept", "title": "Client preference and cultural fit"}, {"id": "173f6191-1222-4bd7-b30a-8ca2d6512db2", "type": "concept", "title": "Accessibility and feasibility"}, {"id": "6aa976aa-3f4b-4330-9e11-dd3f545d5c7f", "type": "concept", "title": "Roles, timeline, and outcome monitoring"}], "description": "Offer options, explain tradeoffs, and document a plan the client can understand and influence."}, {"id": "d3363bda-0710-40f3-89ff-417bd0d416b4", "type": "subtopic", "title": "Adaptive planning", "children": [{"id": "a2067ed0-1a4a-46cc-90c9-df7ff1767346", "type": "concept", "title": "Progress and feedback measures"}, {"id": "faaeb1c3-84ad-42ec-b37a-c45c20978741", "type": "concept", "title": "Fidelity versus responsive adaptation"}, {"id": "8564a6c2-076c-4403-8045-dd9e40dfb134", "type": "concept", "title": "Stepped care and consultation"}], "description": "Review response and revise when circumstances, risks, or goals change."}]}, {"id": "2d4494ce-9ed1-4b6f-a6ce-bf67743b8f96", "type": "topic", "title": "5. Crisis Intervention", "description": "Respond to acute distress with calm, structured assessment, immediate safety action, mobilization of supports, and timely follow-up.", "children": [{"id": "29187ab3-df79-41e3-ab7c-7e58fcdc9e10", "type": "subtopic", "title": "Crisis recognition and stabilization", "children": [{"id": "805b4433-232c-4ab4-a506-f57faa68ce4a", "type": "concept", "title": "Psychological first aid principles"}, {"id": "f9fe65f0-248d-4b89-b33d-657f4f7e2f28", "type": "concept", "title": "Grounding and practical problem solving"}, {"id": "b3e77588-1ae4-496c-8b78-ceedf7d37152", "type": "concept", "title": "Medical, psychiatric, and environmental emergencies"}], "description": "Identify precipitants, reactions, coping, supports, and immediate needs while reducing arousal and confusion."}, {"id": "eb88afab-b048-4c06-a697-07f2b1c19a0d", "type": "subtopic", "title": "Risk and protective assessment", "children": [{"id": "c8d1548b-93dd-4448-af82-b97c1f0f479b", "type": "concept", "title": "Ideation, intent, plan, means, and history"}, {"id": "960e07a9-cbb6-4e98-addb-da70ca471334", "type": "concept", "title": "Dynamic and protective factors"}, {"id": "0a5c49f2-19a0-4c0c-b529-e832260086c8", "type": "concept", "title": "Lethal-means safety and emergency escalation"}], "description": "Directly assess suicide, self-harm, violence, abuse, exploitation, substance-related risk, and ability to care for self or dependents."}, {"id": "66641bd1-33b9-411e-8156-e4343f04d29d", "type": "subtopic", "title": "Crisis plan and continuity", "children": [{"id": "262a53f4-1b3f-4137-ba97-6940f1ad7ef1", "type": "concept", "title": "Warning signs and coping steps"}, {"id": "f85a246d-40c9-4a83-8d2a-2fd50d0e6c0d", "type": "concept", "title": "Support people and crisis services"}, {"id": "b89c1f15-b684-4dfd-a5c5-59a7fe317d0b", "type": "concept", "title": "Warm handoff, documentation, and post-crisis review"}], "description": "Develop a collaborative, feasible plan with clear contacts, responsibilities, and follow-up."}]}, {"id": "398c00bf-15ae-450b-b8a9-1d1a45208817", "type": "topic", "title": "6. Cognitive-Behavioral Approaches", "description": "Use structured, collaborative strategies that connect situations, thoughts, emotions, behavior, physiology, and environment.", "children": [{"id": "f675d544-4335-460f-b471-48ef86d5c9f8", "type": "subtopic", "title": "CBT formulation", "children": [{"id": "b51dfc77-6ce4-40cc-95bc-9582fc1d0752", "type": "concept", "title": "Triggers and automatic thoughts"}, {"id": "6145c752-5854-4ee6-b236-ae00ddaade21", "type": "concept", "title": "Emotions, body responses, and behavior"}, {"id": "cb20759f-cbb5-4a34-9e42-7435694fa23f", "type": "concept", "title": "Short-term relief and long-term costs"}], "description": "Map maintaining cycles without blaming clients or ignoring structural conditions."}, {"id": "ee915417-b502-4437-92c9-55053e65faac", "type": "subtopic", "title": "Cognitive and behavioral strategies", "children": [{"id": "113c3aff-3cce-4b0f-b6a4-87d2247c5b4a", "type": "concept", "title": "Behavioral activation and graded tasks"}, {"id": "79a3d2cc-7482-4a79-b273-f28394871364", "type": "concept", "title": "Thought monitoring and balanced alternatives"}, {"id": "e4efe3a3-75cf-45cf-9c6a-6f2f2d0cf729", "type": "concept", "title": "Problem solving, exposure concepts, and coping rehearsal"}], "description": "Practice bounded generalist interventions appropriate to competence and supervision."}, {"id": "d8aea02f-39de-4569-9240-810b03e89ec5", "type": "subtopic", "title": "Skill consolidation", "children": [{"id": "1c2c11f7-1325-4970-b147-f75c0e47ee74", "type": "concept", "title": "Homework as collaborative experiment"}, {"id": "75daf132-14d4-4ff5-bca9-8a76f9d4b10c", "type": "concept", "title": "Progress monitoring"}, {"id": "4c2872a7-06a7-4239-8b7b-3dd27e13d86d", "type": "concept", "title": "Maintenance and warning-sign plans"}], "description": "Use practice, feedback, measurement, and relapse planning to support transfer beyond meetings."}]}, {"id": "61e188d7-1dee-4cf9-bd79-24f3ab54e904", "type": "topic", "title": "7. Solution-Focused Practice", "description": "Amplify goals, exceptions, capabilities, and small next steps while remaining attentive to risk, trauma, and structural barriers.", "children": [{"id": "d6cdc90f-c0c6-4a22-a69d-383ff8331caf", "type": "subtopic", "title": "Preferred future", "children": [{"id": "d0059c81-da15-41b4-a42d-157eed1c4eab", "type": "concept", "title": "Miracle and future-oriented questions"}, {"id": "f499e0ad-ca1b-4036-b25a-773dcedfba21", "type": "concept", "title": "Observable signs of change"}, {"id": "8ed08e7c-e31a-4fa5-81e5-1b2be67807e8", "type": "concept", "title": "Client language and priorities"}], "description": "Elicit concrete descriptions of what improvement would look like in daily life."}, {"id": "7f22abc5-ac06-4282-b17c-8dee23dd2d73", "type": "subtopic", "title": "Exceptions and resources", "children": [{"id": "bf1ce4ff-eda5-4b9b-9e7c-f034eaa9f7bf", "type": "concept", "title": "Exception questions"}, {"id": "b1cf5803-61c0-425e-bb56-64be41d9f1da", "type": "concept", "title": "Coping and survival questions"}, {"id": "bcd56768-7d8a-43eb-8d7f-2dc8730cacdc", "type": "concept", "title": "Scaling confidence, progress, and importance"}], "description": "Explore when the concern is absent, less intense, or managed differently."}, {"id": "6acc40a6-9206-4472-a86e-d064ce4d7b7c", "type": "subtopic", "title": "Small-step experimentation", "children": [{"id": "4fd69b18-4fa2-4ff2-8ae4-9fbebc24f50a", "type": "concept", "title": "Client-generated next steps"}, {"id": "ae7efb63-e1ee-40e8-b5fa-4e9ad8ba310b", "type": "concept", "title": "Compliments grounded in evidence"}, {"id": "ee79cd79-021c-4bf1-9a97-ae275f7c5cf5", "type": "concept", "title": "Follow-up and revision"}], "description": "Co-design achievable actions and learn from the response."}]}, {"id": "acd2a35d-dfaf-4f58-9697-3a0b2cd192e8", "type": "topic", "title": "8. Motivational Interviewing", "description": "Strengthen a person’s own reasons and confidence for change through partnership, acceptance, compassion, and evocation.", "children": [{"id": "90a3aae5-8208-4124-aaeb-4508450a4eab", "type": "subtopic", "title": "MI spirit and processes", "children": [{"id": "6d5b667a-c05e-47d3-9393-8840bfb88a7e", "type": "concept", "title": "Autonomy support"}, {"id": "4e0f5514-e562-4d07-b3ce-209ecbca3d39", "type": "concept", "title": "Accurate empathy"}, {"id": "5793a80f-b4cf-4a93-8d41-5abf9f160161", "type": "concept", "title": "Avoiding the fixing reflex"}], "description": "Apply partnership through engaging, focusing, evoking, and planning."}, {"id": "d4fab67e-3a94-474c-a9ce-0061abe9f3c0", "type": "subtopic", "title": "Change conversation skills", "children": [{"id": "1ffaf3ef-62a8-49d2-80b5-87fc154ae6b4", "type": "concept", "title": "Open questions, affirmations, reflections, and summaries"}, {"id": "2a55cb95-48dc-4e59-ab9c-7847f2bd690e", "type": "concept", "title": "Change talk and sustain talk"}, {"id": "958381eb-abe6-4957-bbd5-ed0edd208164", "type": "concept", "title": "Elicit–provide–elicit information exchange"}], "description": "Use OARS and selective responses to evoke and strengthen change talk."}, {"id": "f9754927-daa3-447e-8f46-dd767e893507", "type": "subtopic", "title": "Planning and fidelity", "children": [{"id": "978d7f86-c12d-4296-8f9d-f5fca0c9440c", "type": "concept", "title": "Readiness and commitment language"}, {"id": "872d9ed8-16ee-4747-a7d6-1722a35ddc5f", "type": "concept", "title": "Change plan and confidence"}, {"id": "01124d43-df0c-451c-9d70-b891494c3573", "type": "concept", "title": "MITI concepts and supervision feedback"}], "description": "Move toward a plan when readiness emerges and monitor whether practice remains MI-consistent."}]}, {"id": "8ab9c1f9-8653-4dc3-996b-eee3cf3af7e8", "type": "topic", "title": "9. Family Therapy Basics", "description": "Use family-systems concepts and foundational family-practice skills within generalist competence and appropriate supervision.", "children": [{"id": "502bf41e-c57d-4fe7-a749-b2abce167781", "type": "subtopic", "title": "Systems perspective", "children": [{"id": "12c3691a-c212-454d-9693-6c7676efe88f", "type": "concept", "title": "Circular rather than linear causality"}, {"id": "ce0c555b-7648-4a60-89f7-64140fa8bc31", "type": "concept", "title": "Family life cycle and transitions"}, {"id": "cf1efcb6-cabc-48ad-9ca1-197354184a6e", "type": "concept", "title": "Intergenerational and ecological influences"}], "description": "Understand reciprocal patterns, roles, boundaries, subsystems, development, culture, and context."}, {"id": "865652e7-1692-4209-bedf-f85aa31fffc8", "type": "subtopic", "title": "Family engagement and assessment", "children": [{"id": "5e041ac6-45b9-4544-a35a-e1e1903e5105", "type": "concept", "title": "Joining and multipartiality"}, {"id": "75cb913b-2b60-4ae1-a639-3eede432c3da", "type": "concept", "title": "Genograms, interactional sequences, and strengths"}, {"id": "05fd54df-01e9-4af9-9058-8d2811ce3f64", "type": "concept", "title": "Child voice, consent, and caregiver authority"}], "description": "Create balanced participation and map patterns without assigning one member as the problem."}, {"id": "217ef5a9-53e5-4abd-9647-6ad787d09331", "type": "subtopic", "title": "Foundational interventions", "children": [{"id": "e4dc37a9-8476-478d-87a6-f95814a3e9a4", "type": "concept", "title": "Enactment and interaction observation"}, {"id": "23abad40-ff9e-4185-8053-6bc3395fc1c5", "type": "concept", "title": "Psychoeducation and structured tasks"}, {"id": "124214ee-e2ce-4ce2-b949-d0a66a49159a", "type": "concept", "title": "Intimate partner violence and conjoint-work contraindications"}], "description": "Use reframing, communication coaching, problem solving, and boundary clarification while recognizing referral needs."}]}, {"id": "415b26af-0c2e-4079-a994-4859541d40c5", "type": "topic", "title": "10. Termination and Evaluation", "description": "End services intentionally, review outcomes and meaning, consolidate learning, plan continuity, and address the relationship.", "children": [{"id": "ce171b4e-f422-41a2-86df-208e34dddb6b", "type": "subtopic", "title": "Preparing for ending", "children": [{"id": "60380d4a-0810-486b-865b-377e369a7c2d", "type": "concept", "title": "Planned and unplanned endings"}, {"id": "ee35fcde-5df3-4d5a-b1f6-73b6166d05a7", "type": "concept", "title": "Worker and client reactions"}, {"id": "484983fb-f57e-487a-a635-5dc8f6be73b9", "type": "concept", "title": "Abandonment and continuity risks"}], "description": "Discuss timing and feelings early enough to prevent abrupt or avoidant closure."}, {"id": "8ee7603f-e310-4a20-9272-79a3f95f9f4c", "type": "subtopic", "title": "Outcome and process review", "children": [{"id": "72a339c2-2bc3-409a-96fa-dbfca6dd361e", "type": "concept", "title": "Goal attainment and standardized measures"}, {"id": "0b031da4-46ac-4f65-b620-ff9f75f34a64", "type": "concept", "title": "Client-defined change"}, {"id": "ce0370d0-dd01-4387-9494-3f953959d6ea", "type": "concept", "title": "Intervention and alliance feedback"}], "description": "Compare goals, baseline, feedback, and lived experience to evaluate benefit, harm, and unfinished work."}, {"id": "2aa2dffe-19a9-4a37-9824-2af0f8c9abce", "type": "subtopic", "title": "Transition and maintenance", "children": [{"id": "eed2c777-75d5-4872-94cd-083a1bf71b01", "type": "concept", "title": "Relapse and crisis planning"}, {"id": "780199a8-23db-496d-b239-76db102c2032", "type": "concept", "title": "Referral and transfer summaries"}, {"id": "3a7a11d6-da47-4c70-a8ac-fd09a2e0a576", "type": "concept", "title": "Re-entry options and follow-up"}], "description": "Consolidate skills, anticipate setbacks, connect supports, and document closure."}]}, {"id": "3091d308-8cce-4a4d-8327-3750c04a710d", "type": "topic", "title": "11. Mandated Reporting, Safety Planning, and Coordinated Referrals", "description": "Act lawfully and ethically when safety concerns arise while preserving dignity, transparency, and continuity wherever possible.", "children": [{"id": "36d6fd9a-648a-460c-a2b6-d7d5879ffd1c", "type": "subtopic", "title": "Mandated reporting", "children": [{"id": "a2036b86-6452-455f-a584-426f2566d3ad", "type": "concept", "title": "Child and vulnerable-adult maltreatment"}, {"id": "68ac06b3-70bd-4904-83f1-89abcb9944dc", "type": "concept", "title": "Imminent danger and duty-to-protect concepts"}, {"id": "c246643d-f7be-4fb7-8ccc-daced12ab3c0", "type": "concept", "title": "Explaining limits of confidentiality"}], "description": "Know jurisdiction-specific duties, thresholds, procedures, documentation, and consultation pathways."}, {"id": "ab419dcf-3d83-4d78-86be-5181219745d4", "type": "subtopic", "title": "Collaborative safety planning", "children": [{"id": "76e200b6-3621-4d49-9ed2-102225428c62", "type": "concept", "title": "Warning signs and internal coping"}, {"id": "9fcf995d-8dc3-4c27-b43f-cf77c6061b2d", "type": "concept", "title": "Social supports and professional contacts"}, {"id": "cd1fdc43-9b44-4218-a324-0d2c698cfc4e", "type": "concept", "title": "Environmental and lethal-means safety"}], "description": "Create individualized, practical plans rather than relying on generic promises of safety."}, {"id": "c3b39803-94ac-4fc2-86b2-ea49f6de930d", "type": "subtopic", "title": "Coordinated referral", "children": [{"id": "e94e000f-6afe-4ca5-a2d4-c9afccf99b9c", "type": "concept", "title": "Resource verification and barrier reduction"}, {"id": "6c49bbae-20bc-490b-852a-4b49d884331f", "type": "concept", "title": "Warm handoffs and releases of information"}, {"id": "d58e12e7-281d-4660-92fb-7ad57ff247f9", "type": "concept", "title": "Follow-up ownership and failed-referral plans"}], "description": "Match need, eligibility, access, culture, urgency, and client preference, then close the loop."}]}, {"id": "2befe434-8938-4465-8495-1ec5ad1b2106", "type": "topic", "title": "12. Ethics, Boundaries, Documentation, and Technology", "description": "Use professional authority responsibly through ethical reasoning, clear boundaries, defensible records, privacy protection, and safe technology use.", "children": [{"id": "6eed820c-6d25-4596-ac88-2bf94da4cc45", "type": "subtopic", "title": "Ethical decision-making", "children": [{"id": "1a411cc9-5b3f-4830-8c6c-79a4a78dac40", "type": "concept", "title": "Self-determination and foreseeable harm"}, {"id": "ecd71b96-14c6-4df1-921f-0ea73ad0470c", "type": "concept", "title": "Conflicts of interest and dual relationships"}, {"id": "0c6691d3-505b-4c8b-95f9-9081f6945d4b", "type": "concept", "title": "Competence, supervision, and impairment"}], "description": "Apply the NASW Code, law, policy, consultation, and principled reasoning to competing obligations."}, {"id": "6cfd68df-92ce-4cd8-835b-be6870efd255", "type": "subtopic", "title": "Boundaries and professional use of self", "children": [{"id": "3a9d4884-72b1-42b1-aeec-45a4c4cf4956", "type": "concept", "title": "Gifts, touch, social contact, and social media"}, {"id": "93459f87-3d28-4408-a590-2acef5c7a738", "type": "concept", "title": "Countertransference and emotional reactions"}, {"id": "56c4b5ef-5eb6-42fb-a973-d674c811ebff", "type": "concept", "title": "Power, dependence, and ending"}], "description": "Use authenticity and self-disclosure only when they serve client goals and preserve role clarity."}, {"id": "a175c5ee-5417-42ae-ae06-2c11c4724433", "type": "subtopic", "title": "Documentation and digital practice", "children": [{"id": "c5c9434e-9244-4c3f-ae8d-3d529b56da1e", "type": "concept", "title": "SOAP/DAP-style structure and clinical reasoning"}, {"id": "365e5e62-4487-4850-93de-2c4b67e48d3a", "type": "concept", "title": "Minimum necessary disclosure and releases"}, {"id": "d68e186e-16c6-4089-803e-58b662b6e278", "type": "concept", "title": "Telepractice consent, identity, location, privacy, and emergency plans"}], "description": "Create timely, objective, useful records and protect information across in-person and electronic services."}]}, {"id": "cad8b0ba-310e-4481-8bfa-6d929c5f8498", "type": "topic", "title": "13. Anti-Oppressive, Culturally Responsive, and Trauma-Informed Practice", "description": "Integrate cultural humility, power analysis, intersectionality, trauma knowledge, accessibility, and client expertise throughout practice.", "children": [{"id": "e4b7ba77-99a0-4374-bfa9-ca74d70e4ca6", "type": "subtopic", "title": "Cultural humility and anti-oppressive practice", "children": [{"id": "cc3fbc34-4cda-46d5-a257-e0f72564fabf", "type": "concept", "title": "Intersectionality and structural oppression"}, {"id": "60211863-e3c2-4aa6-9099-7f971f8546c3", "type": "concept", "title": "Microaggressions and repair"}, {"id": "c038869f-263b-4866-b3fe-52e8aabeb011", "type": "concept", "title": "Language access and culturally responsive adaptation"}], "description": "Examine positionality and institutional power while treating culture as dynamic and client-defined."}, {"id": "3504d75d-afb0-4594-a5b1-8072478a222a", "type": "subtopic", "title": "Trauma- and violence-informed care", "children": [{"id": "21e8c41e-a990-4f0d-a7b9-a163e5bc5512", "type": "concept", "title": "Trauma responses and window of tolerance"}, {"id": "82e5206d-110e-4c85-9a34-30a84145cf9f", "type": "concept", "title": "Avoiding retraumatization"}, {"id": "cf367e41-cea8-4316-919a-f3307e8992e6", "type": "concept", "title": "Historical, racial, community, and intergenerational trauma"}], "description": "Promote safety, trust, choice, collaboration, and empowerment without requiring disclosure."}, {"id": "5005f6b2-f7b7-47cf-89b1-39d1c4dc6ac3", "type": "subtopic", "title": "Accessibility and inclusion", "children": [{"id": "eb212579-3cce-42df-b57f-eeb60de8d4e6", "type": "concept", "title": "Universal design and accommodations"}, {"id": "11137e16-3db5-4a6e-a753-5e196635904a", "type": "concept", "title": "Supported decision-making"}, {"id": "75424a50-de7e-43e9-8c9e-31f948f0d1c7", "type": "concept", "title": "Strengths-based neurodiversity practice"}], "description": "Adapt engagement and interventions for disability, neurodiversity, literacy, age, language, gender, sexuality, and digital access."}]}, {"id": "17e0081b-0a30-48a4-b593-67567af62dac", "type": "topic", "title": "14. Evidence-Informed Integrative Practice and Common Presenting Concerns", "description": "Integrate research, practice wisdom, client preferences, culture, feedback, and scope when responding to common concerns.", "children": [{"id": "02476bfd-8ece-48a1-99dc-b6096e4def9e", "type": "subtopic", "title": "Evidence-informed decision-making", "children": [{"id": "138ab5d8-30d8-4991-b9c1-d662e45ceb06", "type": "concept", "title": "Research evidence and practice guidelines"}, {"id": "33bbd010-86d8-442d-af39-a85702d1b78d", "type": "concept", "title": "Client values and contextual feasibility"}, {"id": "f6f6310b-21fc-459e-9086-77db1f004c4d", "type": "concept", "title": "Measurement-based and feedback-informed care"}], "description": "Ask answerable questions, appraise fit and quality, and adapt evidence transparently."}, {"id": "65f00b81-18eb-4989-943f-875ff5708ce4", "type": "subtopic", "title": "Common concerns", "children": [{"id": "59dfbbd9-4647-42b2-8b4c-7f41f04ece4e", "type": "concept", "title": "Anxiety, depression, grief, and adjustment"}, {"id": "9fa2188f-2443-4656-9386-d6e580be172e", "type": "concept", "title": "Substance use, trauma, and relationship conflict"}, {"id": "435dd41e-eb89-4fde-9b5c-67fbaa8e9ce2", "type": "concept", "title": "Chronic illness, caregiving, and social isolation"}], "description": "Recognize broad patterns and first-line generalist responses without overstepping diagnostic or treatment competence."}, {"id": "874104ee-ffc3-4a1e-a3cf-0ea2e08d9fb2", "type": "subtopic", "title": "Integrative formulation", "children": [{"id": "27f312e2-7503-4278-b683-7e38e679ce26", "type": "concept", "title": "Common factors and therapeutic alliance"}, {"id": "4e0c82a0-fbc0-4cf8-9e11-fa4b531e41a9", "type": "concept", "title": "Case complexity and comorbidity"}, {"id": "00958ede-1836-4e6b-9ede-6c0d550ecbcb", "type": "concept", "title": "Referral for specialized assessment or treatment"}], "description": "Select and sequence relational, behavioral, cognitive, motivational, family, environmental, and advocacy strategies."}]}, {"id": "0e193759-456a-47af-b9f7-71a571578a9a", "type": "topic", "title": "15. Case Coordination, Interprofessional Practice, Supervision, and Practitioner Sustainability", "description": "Coordinate care across systems, use supervision as a safety and learning mechanism, and sustain ethical effectiveness over time.", "children": [{"id": "c443ffd1-7390-4e59-9d35-ae6c683ef6f0", "type": "subtopic", "title": "Case management and advocacy", "children": [{"id": "d9555f57-4567-4fad-a26a-fa969bd45e61", "type": "concept", "title": "Benefits, housing, health, education, legal, and community resources"}, {"id": "2c9e57bd-d6be-4c09-9882-2ea355c01db3", "type": "concept", "title": "Care plans and service coordination"}, {"id": "14cbd451-8121-49de-9a38-f9c71cd7da38", "type": "concept", "title": "Client advocacy and systems barriers"}], "description": "Help clients navigate fragmented systems while addressing concrete barriers and rights."}, {"id": "c1ec7bd3-ed7e-4cd7-99a3-fba8e7e7e9b7", "type": "subtopic", "title": "Interprofessional collaboration", "children": [{"id": "198788b4-4298-4f33-a70b-d3a1b969ad05", "type": "concept", "title": "Team roles and scope"}, {"id": "99efef53-59fc-4461-88f2-27fa4394e1e4", "type": "concept", "title": "Case conferencing and shared plans"}, {"id": "9c43cecd-d212-4edb-a09a-2a8a3c7ef196", "type": "concept", "title": "Conflict resolution and closed-loop communication"}], "description": "Communicate role, risk, goals, and relevant information clearly with consent and respect."}, {"id": "6c2333a2-33bd-4741-83f6-0dc3000d32b7", "type": "subtopic", "title": "Supervision and sustainability", "children": [{"id": "fb712dab-e50c-44ed-99f0-4a3190e5d116", "type": "concept", "title": "Case presentation and focused consultation"}, {"id": "6a2c7e1d-b077-443f-8b6d-77390e259d4d", "type": "concept", "title": "Vicarious trauma, moral distress, burnout, and impairment"}, {"id": "4c43ee8e-c331-4260-a65a-9cdf8460fc35", "type": "concept", "title": "Reflective practice, peer support, workload, and organizational responsibility"}], "description": "Prepare for supervision, recognize limits, reflect on practice, and respond to occupational stress."}]}], "dbBacked": true}$swifjson$::jsonb,
